package com.example.starter.error;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.MissingRequestHeaderException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.time.LocalDateTime;
import java.util.stream.Collectors;

/**
 * 全局异常映射：业务异常按携带状态码返回；参数校验/请求解析失败返回 400；其余异常返回 500。
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<ErrorBody> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.status())
                .body(new ErrorBody(ex.status().value(), ex.getMessage(), LocalDateTime.now()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorBody> handleValidation(MethodArgumentNotValidException ex) {
        String message = ex.getBindingResult().getFieldErrors().stream()
                .map(FieldError::getField)
                .distinct()
                .collect(Collectors.joining(", ", "参数非法: ", ""));
        return ResponseEntity.badRequest()
                .body(new ErrorBody(400, message, LocalDateTime.now()));
    }

    @ExceptionHandler({MissingRequestHeaderException.class, HttpMessageNotReadableException.class})
    public ResponseEntity<ErrorBody> handleBadRequest(Exception ex) {
        return ResponseEntity.badRequest()
                .body(new ErrorBody(400, "参数非法: " + ex.getMessage(), LocalDateTime.now()));
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorBody> handleOther(Exception ex) {
        log.error("未处理异常", ex);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(new ErrorBody(500, "服务内部错误", LocalDateTime.now()));
    }

    /**
     * 统一错误响应体。
     *
     * @param status    HTTP 状态码
     * @param message   错误描述
     * @param timestamp 发生时间（Asia/Shanghai）
     */
    public record ErrorBody(int status, String message, LocalDateTime timestamp) {
    }
}

package com.example.starter.evidence.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.time.LocalDateTime;

/**
 * 限时借出请求。仅当前保管人可发起，借用人必须与保管人不同；
 * dueAt 为 UTC 应还时刻，须晚于服务端当前时刻且不超过 72 小时。
 *
 * @param commandKey 幂等命令键
 * @param loanKey    借出业务键，全局唯一
 * @param borrowerId 实际借用人
 * @param purpose    借出用途，非空
 * @param dueAt      UTC 应还时刻
 */
public record LoanCreateRequest(
        @NotBlank @Size(max = 64) String commandKey,
        @NotBlank @Size(max = 64) String loanKey,
        @NotBlank @Size(max = 64) String borrowerId,
        @NotBlank @Size(max = 512) String purpose,
        @NotNull LocalDateTime dueAt) {
}

package com.example.starter.evidence.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 归还确认请求。仅借出时的当前保管人可确认，借用人不能代为确认；
 * 必须指定本次借出的 loanKey、封条是否完好及非空说明。
 *
 * @param commandKey 幂等命令键
 * @param loanKey    本次借出的业务键
 * @param sealIntact 封条是否完好：true 完好回到 SEALED / false 异常进入 SEAL_BROKEN
 * @param note       归还说明，非空
 */
public record LoanReturnRequest(
        @NotBlank @Size(max = 64) String commandKey,
        @NotBlank @Size(max = 64) String loanKey,
        @NotNull Boolean sealIntact,
        @NotBlank @Size(max = 512) String note) {
}

