                itemId, PackageItemStatus.OUT.name());
        return updated == 1;
    }

    private static final class ItemRowMapper implements RowMapper<LoanPackageItem> {
        @Override
        public LoanPackageItem mapRow(ResultSet rs, int rowNum) throws SQLException {
