                    rs.getString("evidence_key"),
                    rs.getLong("seal_version"),
                    rs.getInt("item_seq"),
                    PackageItemStatus.valueOf(rs.getString("status")),
                    returnedBatchId,
                    rs.getObject("returned_at", LocalDateTime.class),
                    rs.getObject("created_at", LocalDateTime.class));
        }
    }
}

